package io.github.jesterportfolio.hearth.gathering;

import java.util.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;

/** 제한된 구역형 채집 인던의 공개 합성 정의. 운영 인던의 물리 배치를 확정하지 않습니다. */
public record GatheringContent(String id,Box area,Position entrance,Position spawn,long intervalMillis,long warningMillis,String active,Map<String,Template> templates){
    public record Position(double x,double y,double z,float yaw,float pitch){public Position{if(!Double.isFinite(x)||!Double.isFinite(y)||!Double.isFinite(z)||!Float.isFinite(yaw)||!Float.isFinite(pitch)||Math.abs(x)>29999984||Math.abs(z)>29999984||y< -64||y>320||Math.abs(pitch)>90)throw new IllegalArgumentException("GATHERING_POSITION");}}
    public record Cell(int x,int y,int z){}
    public record Box(int x,int y,int z,int width,int height,int depth){public Box{if(width<1||height<1||depth<1||(long)width*height*depth>4096||y< -64||y+height>320||Math.abs((long)x)+width>29999984||Math.abs((long)z)+depth>29999984)throw new IllegalArgumentException("GATHERING_BOUNDS");}public List<Cell> cells(){var r=new ArrayList<Cell>();for(int dx=0;dx<width;dx++)for(int dy=0;dy<height;dy++)for(int dz=0;dz<depth;dz++)r.add(new Cell(x+dx,y+dy,z+dz));return List.copyOf(r);}public boolean contains(double x,double y,double z){return x>=this.x&&x<this.x+width&&y>=this.y&&y<this.y+height&&z>=this.z&&z<this.z+depth;}public String hash(){return digest(toString());}}
    public record Template(String version,Map<Cell,String> blocks){public Template{key(version);blocks=Map.copyOf(blocks);if(blocks.isEmpty()||blocks.size()>4096||blocks.values().stream().anyMatch(s->!Set.of("AIR","STONE","DIRT","COBBLESTONE","IRON_ORE","COPPER_ORE","COAL_ORE").contains(s)))throw new IllegalArgumentException("GATHERING_TEMPLATE");}public String hash(){return digest(version+blocks.entrySet().stream().sorted(Comparator.comparing(e->e.getKey().toString())).toList());}}
    public GatheringContent{key(id);Objects.requireNonNull(entrance);Objects.requireNonNull(spawn);if(area.contains(entrance.x(),entrance.y(),entrance.z())||!area.contains(spawn.x(),spawn.y(),spawn.z()))throw new IllegalArgumentException("GATHERING_ENTRY_POSITION");templates=Map.copyOf(templates);if(intervalMillis<100||intervalMillis>2592000000L||warningMillis<0||warningMillis>=intervalMillis||templates.isEmpty()||templates.size()>16||!templates.containsKey(active)||templates.values().stream().anyMatch(t->!t.blocks().keySet().equals(new HashSet<>(area.cells()))))throw new IllegalArgumentException("GATHERING_CONTENT");}
    public static GatheringContent parse(Map<?,?> m){if(!(m.get("format") instanceof Number f)||f.intValue()!=1||!Boolean.TRUE.equals(m.get("isolated-region-prototype")))throw new IllegalArgumentException("GATHERING_FORMAT");var a=map(m.get("area"));var area=new Box(n(a,"x"),n(a,"y"),n(a,"z"),n(a,"width"),n(a,"height"),n(a,"depth"));var templates=new LinkedHashMap<String,Template>();for(var value:(List<?>)m.get("templates")){var row=map(value);String version=text(row,"version");var cells=new LinkedHashMap<Cell,String>();for(var c:area.cells())cells.put(c,"AIR");for(var value2:(List<?>)row.get("layers")){var layer=map(value2);int y=n(layer,"y");if(y<area.y()||y>=area.y()+area.height())throw new IllegalArgumentException("GATHERING_LAYER");for(var c:area.cells())if(c.y()==y)cells.put(c,text(layer,"material"));}for(var value2:(List<?>)row.get("blocks")){var b=map(value2);var c=new Cell(n(b,"x"),n(b,"y"),n(b,"z"));if(!cells.containsKey(c))throw new IllegalArgumentException("GATHERING_CELL");cells.put(c,text(b,"material"));}if(templates.put(version,new Template(version,cells))!=null)throw new IllegalArgumentException("GATHERING_DUPLICATE");}return new GatheringContent(text(m,"id"),area,position(map(m.get("entrance"))),position(map(m.get("spawn"))),number(m,"interval-ms"),number(m,"warning-ms"),text(m,"active-template"),templates);}
    private static Position position(Map<?,?> m){return new Position(d(m,"x"),d(m,"y"),d(m,"z"),(float)d(m,"yaw"),(float)d(m,"pitch"));}private static double d(Map<?,?> m,String k){if(!(m.get(k) instanceof Number n))throw new IllegalArgumentException("GATHERING_POSITION");return n.doubleValue();}
    private static Map<?,?> map(Object x){if(!(x instanceof Map<?,?> m))throw new IllegalArgumentException("GATHERING_MAP");return m;}private static String text(Map<?,?> m,String k){if(!(m.get(k) instanceof String s)||s.isBlank())throw new IllegalArgumentException("GATHERING_TEXT");return s;}private static int n(Map<?,?> m,String k){if(!(m.get(k) instanceof Number n)||n.doubleValue()!=n.intValue())throw new IllegalArgumentException("GATHERING_NUMBER");return n.intValue();}
    private static long number(Map<?,?> m,String k){if(!(m.get(k) instanceof Number n)||n.doubleValue()!=n.longValue())throw new IllegalArgumentException("GATHERING_NUMBER");return n.longValue();}
    static void key(String x){if(x==null||!x.matches("[a-z][a-z0-9_]{0,63}"))throw new IllegalArgumentException("GATHERING_KEY");}static String digest(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
}
